rows = data_rows('Paired measurements', {'B': 'string', 'C': 'number', 'D': 'number'}, 908, 913)
y_vals = [num('Paired measurements', 'C' + str(r)) for r in rows]
x_vals = [num('Paired measurements', 'D' + str(r)) for r in rows]

def compute_ranks(vals):
    n = len(vals)
    indexed = sorted(enumerate(vals), key=lambda x: x[1])
    ranks = [0.0] * n
    i = 0
    while i < n:
        j = i
        while j < n and indexed[j][1] == indexed[i][1]:
            j += 1
        avg_rank = (i + 1 + j) / 2.0
        for k in range(i, j):
            ranks[indexed[k][0]] = avg_rank
        i = j
    return ranks

y_ranks = compute_ranks(y_vals)
x_ranks = compute_ranks(x_vals)

mean_y = sum(y_ranks) / len(y_ranks)
